@theme inline {
  --font-display: var(--font-doto), ui-monospace, monospace;
  --font-mono: var(--font-ibm-plex-mono), ui-monospace, SFMono-Regular, Menlo, monospace;
}

html,
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background-color: #0A0B09;
  color: #EEEBD8;
  overflow: hidden;
}

/* Custom hairline range sliders for developer inspection dock */
input[type="range"].dither-slider {
  -webkit-appearance: none;
  appearance: none;
  background: rgba(211, 208, 186, 0.16);
  height: 2px;
  border-radius: 1px;
  outline: none;
}

input[type="range"].dither-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 10px;
  height: 10px;
  background: #A8F23A;
  border: 1px solid #0A0B09;
  cursor: pointer;
}

input[type="range"].dither-slider::-moz-range-thumb {
  width: 10px;
  height: 10px;
  background: #A8F23A;
  border: 1px solid #0A0B09;
  border-radius: 0;
  cursor: pointer;
}

